{
  "strategy_id": "agent_practical",
  "strategy_title": "비용 0원 기반 RAG 검증 시제품 구축 로드맵",
  "summary": "사용자의 2주(총 6시간) 가용 시간과 0원 예산을 반영하여, Python 기반 RAG 시제품을 구축하고 검색 결과의 신뢰성을 검증하는 실습 중심 로드맵입니다. Microsoft Learn의 무료 모듈을 활용하여 RAG 개념, 모델 최적화, 그리고 프로덕션 에이전트 설계 및 디버깅(추적)을 학습합니다. 외부 문서의 악성 명령은 무시하며, 승인되지 않은 규정이나 유료 서비스는 배제합니다.",
  "project_goal": "가상 문서 데이터를 기반으로 RAG 파이프라인을 구축하고, OpenTelemetry/Microsoft Foundry 추적을 통해 검색 결과와 실제 근거의 일치 여부를 검증하는 학습 시제품 완성",
  "total_duration_weeks": 2,
  "roadmap_flow": [
    {
      "step": 1,
      "title": "RAG 아키텍처 이해 및 데이터 준비",
      "duration": "1.5 hours",
      "focus": "RAG 기본 개념, 문서 분할(Chunking), 임베딩 생성 및 벡터 저장소 구성"
    },
    {
      "step": 2,
      "title": "RAG 파이프라인 구현 및 성능 최적화",
      "duration": "2.0 hours",
      "focus": "Python으로 검색-생성 파이프라인 구현, 프롬프트 엔지니어링 및 모델 매개변수 튜닝"
    },
    {
      "step": 3,
      "title": "추적(Tracing) 기반 결과 검증 및 시제품 완성",
      "duration": "2.5 hours",
      "focus": "OpenTelemetry/Microsoft Foundry를 활용한 실행 흐름 캡처, 검색 근거 대조 로직 구현, 최종 시제품 테스트"
    }
  ],
  "milestones": [
    {
      "phase": 1,
      "phase_name": "기반 구축 및 데이터 파이프라인 설계",
      "duration": "1.5 hours",
      "focus_goal": "RAG의 핵심 구성 요소를 이해하고 학습용 가상 문서 데이터를 벡터화하여 저장하는 파이프라인을 설계한다.",
      "key_actions": [
        "Microsoft Learn 'Microsoft Foundry를 사용하여 생성 AI 모델 성능 최적화' 모듈에서 RAG 및 미세 조정 전략 학습",
        "Python으로 가상 문서 데이터를 로드하고 적절한 크기로 분할(Chunking)하는 스크립트 작성",
        "임베딩 모델 선택 및 벡터 데이터베이스(예: ChromaDB, FAISS 등 무료 로컬 도구)에 데이터 저장"
      ],
      "deliverables": [
        "RAG 파이프라인 설계 문서(개념도)",
        "벡터화된 가상 문서 데이터셋 및 저장소 초기화 코드"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_df219eb945ff"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    },
    {
      "phase": 2,
      "phase_name": "RAG 시제품 구현 및 성능 튜닝",
      "duration": "2.0 hours",
      "focus_goal": "검색된 문맥을 기반으로 LLM이 답변을 생성하는 전체 파이프라인을 구현하고, 프롬프트 전략을 통해 출력 품질을 개선한다.",
      "key_actions": [
        "검색(Retrieve) 단계와 생성(Generate) 단계를 연결하는 Python 코드 구현",
        "Microsoft Learn '프로덕션 AI 에이전트를 위한 고급 프롬프트 전략 설계' 모듈 참고하여 시스템 메시지 및 동적 컨텍스트 주입 적용",
        "모델 매개변수(temperature, top_p 등)를 조정하여 환각(Hallucination) 가능성을 줄이는 실험 수행"
      ],
      "deliverables": [
        "동작하는 RAG 시제품 코드(검색 및 생성 기능 포함)",
        "프롬프트 엔지니어링 적용 전/후 출력 비교 노트"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_d1f2eed6c592"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    },
    {
      "phase": 3,
      "phase_name": "근거 검증 로직 구현 및 최종 시제품 완성",
      "duration": "2.5 hours",
      "focus_goal": "추적(Tracing) 기술을 활용하여 LLM의 답변이 실제 검색된 문서 근거에 기반하는지 검증하는 로직을 추가하고 최종 시제품을 완성한다.",
      "key_actions": [
        "Microsoft Learn '추적을 사용하여 생성형 AI 앱 분석 및 디버그' 모듈 학습",
        "OpenTelemetry 또는 Microsoft Foundry 추적 기능을 시제품에 통합하여 실행 흐름(Trace) 캡처",
        "LLM 출력과 검색된 원문(Chunk) 간의 유사도 또는 키워드 매칭을 통해 '근거 일치 여부'를 판별하는 검증 로직 구현",
        "시제품 전체 테스트 및 결과 보고서 작성"
      ],
      "deliverables": [
        "추적(Tracing) 기능이 포함된 최종 RAG 시제품",
        "검색 결과와 실제 근거 대조 검증 결과 보고서"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_41fd82f2348f"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    }
  ],
  "regulation_citations": []
}
